"""Authored profile expansions. Facts are paired with the pinned baseline sources.

The steps and worked examples are editorial trial designs, not claims of runtime tests.
No commands in this file are executed by the report builder.
"""
PROFILES = {}

def add(key, *, principle, flow, mechanism, rows, steps, command, task, acceptance, tradeoff, sources="", kind="source"):
    PROFILES[key] = dict(principle=principle, flow=flow, mechanism=mechanism,
        rows=rows, steps=steps, command=command, task=task, acceptance=acceptance,
        tradeoff=tradeoff, sources=sources, kind=kind)

add("A13",
    principle="对长期在终端里工作的人，交互本身会影响代理是否好用。工具正在做什么、错误能不能看清、插话和恢复是否顺手，都会改变人工参与成本。Crush 把这些体验放进产品重点，同时保留开放模型与工具接入。它适合把终端当作主工作台的人，而不要求用户为了 AI 换一套 IDE。",
    flow=["终端界面\n输入、状态与审阅", "Coordinator\n代理、模型与运行衔接", "大／小模型配置\n主任务及辅助调用", "会话与自动摘要\n保存和继续", "文件／命令／LSP／MCP\n执行与观察", "Agent 层\n工具、消息与队列"],
    mechanism="Coordinator 类似前台调度台，确保界面当前连接的是正确的代理与模型；Agent 层处理实际回合、工具和队列。两者分开有利于处理模型切换和中途输入，但也提醒我们：切换设置并不只是改一个下拉框。主模型承担实现，辅助模型承担某些轻任务，最终成本应合并计算。自动摘要则是为了让当前任务继续，并非另建一套永不遗忘的知识库。",
    rows=[("交互重点", "面向持续使用的终端 UI", "评价长输出、审批、中断和恢复的可理解性"), ("模型组织", "大模型与小模型分开配置", "辅助调用同样可能计费"), ("运行衔接", "Coordinator 管当前代理与模型", "运行中切换后核对实际模型与状态"), ("上下文", "消息队列与自动摘要", "摘要需保留任务约束和验证进度"), ("项目工具", "LSP、MCP 与规则接入", "先让基础编辑稳定，再增加集成"), ("环境", "可在终端及 SSH 场景使用", "远程启动时，文件和凭据位于那台机器")],
    steps=["按官方 README 安装，在测试项目中启动 crush，配置主模型；若使用辅助模型，也记录其型号与费用渠道。", "让它读项目入口并解释测试方法，先保持工具集合简单；检查终端字体、长输出和错误信息是否易读。", "提交一个小修复，在执行中补充约束，观察它是否正确接收而没有遗忘原目标。", "查看结果和 diff，再试中断后继续；确认模型切换、摘要和历史不会让它重复已经完成的动作。", "需要语言语义或外部服务时再接 LSP／MCP。SSH 使用时，单独核对远端目录、网络和凭据，不把它当成本机环境。"],
    command="bash\n# 完成官方安装和 Provider 配置后\ncd /path/to/project\ncrush",
    task="这个日志解析器在空行和非法时间戳处报错。先确认当前行为，再增加容错与对应测试；处理中我会补充一个真实日志样例。",
    acceptance="观察中途提供的样例是否被用于验证，长日志是否淹没关键错误，以及恢复后能否准确继续。对于每天使用终端的人，减少一次错误审批或一次找不到结果的翻屏，也有实际价值。",
    tradeoff="适合终端熟手与远程开发，选择它可以主要基于交互是否顺手。它并不因 UI 精致就自动具备托管工作机或复杂团队编排；有此需求应另比较 OpenHands、Factory。模型策略也应按完整账单与完成质量评估。")

add("A14",
    principle="Vibe 是围绕 Mistral 编程模型组织的原生工具链，同时保留开放实现。它把模型、工具、权限与客户端通过清楚的接口衔接，适合既想直接开发，又希望读懂运行逻辑的人。官方原生适配可以减少部分工具格式摩擦，但某个型号是否最划算，仍取决于任务、服务端部署和失败重试。",
    flow=["CLI 及客户端\n任务、模式与反馈", "Python Agent Loop\n推进回合与上下文", "模型接口\nDevstral 等后端", "事件与历史\n压缩、状态和交付", "工具／子代理\n文件与命令操作", "权限与调用管理\n按模式决定执行"],
    mechanism="执行循环通过事件报告进度，让客户端知道代理是在等待模型、执行工具还是完成任务。对调用者而言，这比把所有输出当作一段普通文字更容易处理取消和审批。不同模式表达不同工作权限：分析、规划和接受编辑不是同一件事。开放模型部署时还多一层约束，服务端的工具模板、上下文长度与吞吐会影响整个循环。",
    rows=[("原生模型", "围绕 Mistral／Devstral 路线适配", "通用新品不自动等于最佳编程后端"), ("运行实现", "Python 循环与可替换接口", "研究时固定模型与工具，逐项改变变量"), ("交互状态", "异步事件传递执行进度", "客户端要正确区分等待、错误与完成"), ("权限模式", "Ask、Plan、接受编辑等模式", "启动前确认实际模式及工具范围"), ("上下文与分工", "压缩、工具和子代理接口", "子代理数量增加后核对总成本与结果集成"), ("开放部署", "可研究适配的开放模型服务", "硬件、模板和服务参数同样属于方案")],
    steps=["按当前安装指南运行 vibe，完成账户或 API 配置；先使用官方建议的模型路线验证基础操作。", "查看当前模式和权限，先要求只分析项目与测试方法；把模式变化与实际工具能力对应起来。", "给出一个小修改，观察从计划到编辑、测试、纠错的完整循环；结合实际运行与测试结果检查改动。", "若使用更小或自部署型号，用同样任务验证工具参数、多轮纠错和上下文承载；记录实际服务配置。", "最后再增加子代理与扩展。让每个子任务有具体输入、交付材料和停止条件，并由主任务统一检查修改。"],
    command="bash\n# 完成官方安装与认证后\ncd /path/to/project\nvibe",
    task="给文件上传模块增加大小限制与清楚的错误提示。保留现有合法上传路径，分别验证边界大小、超限和缺失文件。",
    acceptance="相同任务可用于比较 Devstral 的不同档位。同时记录首轮速度、修改后的测试、格式错误和返工耗时。如果小模型首次便宜但多次误改，整项任务未必便宜。",
    tradeoff="适合 Mistral 生态用户、开放模型试验与 Python 运行时研究。自部署控制更强，同时也要维护推理服务；原生云服务配置更少，却仍有账户和模型更新约束。与 Qwen Code 比较时，优先看你实际需要的模型部署路线。")

add("A15",
    principle="OpenHands 把“代理有一台怎样的工作机”提升为一等问题。许多代码任务会受环境问题影响，例如依赖安装失败、测试数据缺失或产物未保存。将会话与工作空间一起管理，便于把相同任务交给不同运行环境，也便于团队批量处理问题。代价是环境生命周期本身成为需要维护的软件系统。",
    flow=["Canvas／CLI／调用方\n任务与审查", "会话及 Agent Server\n管理运行生命周期", "SDK 代理／ACP 后端\n各自调用模型", "事件、补丁与产物\n保存后交付", "工作空间\n本机／Docker／集群", "工具与环境接口\n文件、命令等能力"],
    mechanism="Canvas 是用户看任务的地方，SDK 和 Agent Server 承担执行与服务责任，工作空间提供实际文件和进程。三者可以分开部署，因此重启界面、结束会话与销毁工作机不是同一个动作。选择 ACP 后端还可能换掉代理循环。做架构比较时应完整写成“Canvas＋哪种代理＋哪种工作空间”，否则无法判断结果来自模型、环境还是前端。",
    rows=[("项目拆分", "Canvas 与 Software Agent SDK 分仓", "研究执行逻辑需进入 SDK，而非只看前端"), ("执行后端", "原生 SDK 或 ACP 代理", "后端不同，模型与权限也可能不同"), ("工作空间", "本机、容器、集群等路线", "支持容器不等于当前任务默认已隔离"), ("依赖准备", "环境是完整任务的一部分", "记录镜像、安装脚本和可用资源"), ("成果保存", "会话事件与代码产物", "回收环境前确认补丁、日志已可取回"), ("规模化", "可组合会话服务与多工作空间", "还需配额、凭据、排队与资源清理")],
    steps=["按当前 Canvas／SDK 文档选一条最小使用路线，明确代理后端和工作空间类型；安装与配置步骤以当前分仓文档为准。", "用一个小仓库验证环境：获取代码、安装依赖、运行原有测试。先把环境问题解决，再评价模型。", "提交独立 issue，要求保存修改与测试结果；确认任务产生的文件位于哪里，以及界面关闭后如何取回。", "重新创建工作空间，验证环境脚本能否重现；再运行同类任务，检查结果是否依赖残留缓存或本机秘密文件。", "批量部署时为任务分配独立工作空间，设置资源回收与凭据范围；交付前汇总补丁，做仓库级验证。"],
    command="text\n建议保存的任务包：\n仓库与提交 → 环境准备脚本 → 原有测试结果\n问题描述 → 预算与模型配置 → 补丁和运行日志\n确认产物可取回后，再回收临时工作空间。",
    task="为这个仓库补齐一个已知 bug 的修复。请在干净环境安装依赖，先运行原有测试，再实现修复；输出补丁、测试日志和可复用的环境准备说明。",
    acceptance="验收分两部分：代码是否正确，环境是否可重建。若只有保留旧容器才能跑通，就还没有形成可靠批量任务流程。还要确认销毁工作空间后补丁与日志仍存在，不能只在临时终端看到成功。",
    tradeoff="适合批量 issue、远程代理平台和可重复实验。个人小修改可能不值得启动与维护独立环境。与 Devin、Jules 比较时，主要取舍是环境控制和自托管责任；与本地 CLI 比较时，则是可复制性与启动成本。")

add("A16",
    principle="Grok Build 将 Grok 的原生编程体验做成可读源码的终端运行时，同时提供脚本与 ACP 入口。它允许研究者查看代理、工具和沙箱等责任边界，但公开同步的代码与正在发放的二进制不应自动视为完全一致。对用户而言，最有价值的起点是先核对实际加载配置，再判断执行行为。",
    flow=["TUI／脚本／ACP\n任务与客户端", "Rust 代理运行时\n会话及工具推进", "模型后端配置\n原生 Grok／自定义服务", "会话事件与结果\n输出及后续工作", "工具与子任务\n文件、命令、工作树", "分层策略与沙箱\n用户、项目、组织约束"],
    mechanism="组织、用户与项目配置代表不同责任范围。组织约束可能不可由项目覆盖；用户默认也可能被当前任务具体设置改变。inspect 这类检查入口会展示合并后的有效状态，便于确认最终生效的配置。脚本模式又减少了实时人工交互，因此权限问题、错误状态和结果格式都应在接入自动化前验证。",
    rows=[("源码范围", "公开 Rust CLI／TUI 与运行时快照", "定期同步不保证与每个商业二进制逐字一致"), ("入口", "交互、脚本与 ACP", "无界面运行需要明确处理失败和审批条件"), ("规则", "项目指令、Skills、Hooks、MCP", "检查实际加载结果及生效范围"), ("配置", "用户、项目与组织分层", "项目配置不能假定覆盖全部管理策略"), ("并行", "子代理、工作树和后台任务", "分开确认上下文、目录和进程生命周期"), ("模型", "原生默认及自定义 API 配置", "更换模型后重新验收工具和输出协议")],
    steps=["安装官方发行版并登录，在项目目录运行 grok；记录版本及实际模型后端，先用原生路线完成一次小任务。", "运行 grok inspect 检查指令、工具和有效设置；核对项目配置是否被组织策略限制。", "让它分析测试方法，再给出范围有限的修改；检查工具权限、沙箱与真实文件变化。", "需要后台子任务时，先分清它运行在哪个目录、怎样取消、结果怎样返回；并行改动再考虑工作树。", "基础稳定后使用 -p 脚本模式，并按文档选结构化输出；自动化程序应处理错误与非完成状态，不只寻找成功文字。"],
    command="bash\ncd /path/to/project\ngrok inspect\ngrok\n# 无交互的小型只读查询示例\ngrok -p '说明这个项目的测试入口并引用文件路径'",
    task="为一个过长的命令处理函数做最小重构，保持外部参数和输出一致。先列出有效项目规则，再实施、运行测试并解释行为兼容性。",
    acceptance="除了代码本身，检查代理是否遵循实际生效的项目规则；如果设置文件说一套、执行行为是另一套，用 inspect 的输出定位配置来源。脚本接入时还要故意提供一个不可满足条件，确认失败能被调用方识别。",
    tradeoff="适合 Grok 用户、终端开发和需要结构化自动化入口的人。开放源码带来可观察性，原生模型带来适配便利；跨服务使用仍需付出兼容测试。组织部署尤其应核对配置最终形成的有效策略，并用执行记录验证。")

add("A17",
    principle="可以把它理解为在可扩展代理底座上做出一组明确产品选择：优先采用 Step 服务、提供现成任务控制，并为静态成果交付增加入口。底层血缘解释了为什么有熟悉的会话与扩展结构，产品层则解释了默认权限、认证、工具和编排为何与原版 Pi 不同。",
    flow=["终端／脚本入口\n用户输入与目标", "Pi 派生 AgentSession\n会话与执行循环", "Step Provider\n动态模型目录与协议", "历史、摘要与目标状态\n恢复和继续", "文件／Shell／MCP／插件\n子代理与可选工作树", "Step 工具层与权限\n可选 workflow 编排"],
    mechanism="一条正常任务仍是“组装上下文→请求模型→检查并执行工具→保存结果→继续或结束”。子代理、goal、cron 和 workflow 是叠加在这条主线上、解决不同问题的能力。使用时应先把基本循环跑通，再按需要增加一种控制方式，才能判断问题出在模型、会话还是高级编排。",
    rows=[],
    steps=["按官方 README 为当前平台安装，确认 step --version；Windows 原生路线仍需核对 beta 限制，必要时采用官方推荐的 WSL。", "进入项目运行 step，用 /login 选择地区及订阅／API 渠道，再用 /model 和 /status 核对可用模型与账户。", "首次任务主动查看 /permissions，选择适合试用的 Ask 或 Read Only；用 /init 整理项目说明，先验证读取、修改和检查这条基础链。", "完成一个可重现的小修复后，查看文件变更与测试结果；使用 step -c 继续，并抽查目标、约束及已完成动作是否正确保留。", "再分别试子代理、目标预算与插件。高级 workflow 按安装包确认可用性；无界面 step -p 则要另行核对审批条件和退出状态。"],
    command="bash\ncd /path/to/project\nstep --version\nstep\n# 继续最近会话\nstep -c",
    task="修复这个静态文档站的失效目录链接，验证页面与锚点，输出修改清单。先只生成本地成果；确认验收后，再按已配置的发布插件流程交付。",
    acceptance="分别验收代码修改、任务恢复和静态发布。网页能上传，不代表链接正确；会话能继续，不代表原来的命令进程仍在；goal 显示完成，也不能代替链接检查。每种能力都应有自己的成功证据。",
    tradeoff="它适合希望采用 Step 模型，又需要现成任务与静态交付流程的终端用户。偏自由扩展可比较 Pi，偏 IDE 交互可比较 Cline，偏全天候远程工作可比较云端代理。新项目的版本稳定性与实际使用规模仍应继续观察。")

add("A01",
    principle="它把不少原来由开发者完成的操作串进同一轮工作：模型发现缺少信息时继续读文件，测试失败时接着诊断。用户的主要工作从逐条复制答案，变成规定目标、提供项目约束和审阅结果。这个自由循环对模糊问题有帮助；反过来，若需求和完成标准始终不清楚，模型也可能持续做看起来有用却没有解决问题的工作。",
    flow=["CLI／IDE 等入口\n目标与中途反馈", "Claude 主会话\n组织本轮上下文", "Claude 服务\n推理并提出工具调用", "执行反馈与历史\n继续或交付", "项目文件／终端／MCP\n执行真实操作", "审批与沙箱\n检查工具执行边界"],
    mechanism="读一个陌生项目时，主代理不必一次加载所有源文件。它可以先搜索入口，再读取有关函数，把运行结果带回下一轮。子代理适合把一大段探索过程放到独立上下文中，交回结论和文件位置；但如果任务需要修改同一组文件，分出去反而可能增加协调。Hooks 适合确定的检查，例如文件修改后的格式化；Skill 适合需要模型理解后执行的一套方法。前者按事件触发，后者仍要经过模型判断。",
    rows=[("项目知识", "CLAUDE.md、记忆和按需使用的 Skills", "把构建命令、目录约定写清楚；按任务需要加载相关手册内容"), ("会话与恢复", "当前历史会影响后续动作；可继续既有对话", "继续聊天不等于恢复已退出的服务进程"), ("任务分工", "独立上下文的子代理；另有 Agent Teams", "先决定需要摘要交接，还是需要真正的团队协作"), ("外部能力", "MCP 接服务，Hooks 接确定性程序", "工具数量增加后，要检查命名、凭据和调用范围"), ("执行控制", "权限决定是否允许；沙箱限制可访问范围", "首次使用时确认实际审批模式及账户默认值"), ("交付与迁移", "文件和 Git diff 可审查；扩展配置有产品语义", "带走代码容易，迁移 Hooks、权限规则还需重新适配")],
    steps=["按官方 Quickstart 为自己的系统安装，运行版本检查；区分订阅登录、Console API 与企业云渠道，确认实际计费账户。", "进入已有项目，先请求说明入口、测试和依赖。核对它引用的文件，修正错误后再把稳定结论放进 CLAUDE.md。", "选择账户可用的模型与权限模式。给出一个可重现的小问题，让它先提出原因，再修改；阅读工具请求中的目录和命令。", "让它运行与改动直接有关的检查，并说明失败是原有问题、环境问题还是新增问题。审查 diff，确认没有顺手扩大需求。", "第二次同类任务再提炼 Skill；大量独立调查再开子代理。需要接外部系统时逐个增加 MCP，并保留一条不用该扩展也能验收的基线任务。"],
    command="bash\n# 先按官方文档安装；把路径替换为自己的仓库\ncd /path/to/project\nclaude --version\nclaude\n# 之后在同一目录继续最近一次会话\nclaude -c",
    task="登录接口在密码错误时返回 500。请定位异常处理路径，增加能重现问题的测试，做最小修复，再运行相关测试。交付时给出变更文件、测试结果和仍未覆盖的情况。",
    acceptance="重点观察它有没有先重现问题、是否读到了真正的异常入口，以及失败后能否依据输出调整方案。若只看最终解释，很容易把有条理的叙述误当成可靠调试。跨文件任务再记录你中途纠正它的次数。",
    tradeoff="选它的理由是原生模型与工具体验配合紧密、日常开发流程完整；代价是执行行为对商业模型和产品更新较敏感。希望研究循环本身的人可对照 Pi；希望在多家模型间反复切换的人可对照 OpenCode。用完整任务比较修改质量、测试结果和恢复表现。",
    sources="[官方上手步骤](https://code.claude.com/docs/en/quickstart)", kind="public")

add("A02",
    principle="它更强调任务的持续执行和结果审查：代理先获得一个明确的工作空间，再围绕文件、命令与验证推进。对于开发者，这意味着一次对话可以形成一组可检查的改动；对于界面开发者，同一核心又能通过协议被不同客户端使用。桌面上的任务管理方便组织工作，但真正决定任务能做什么的是运行位置、权限和所选模型。",
    flow=["CLI／桌面／编辑器\n用户目标与审查", "app-server／核心\n任务、回合与事件", "模型接口\n推理及工具请求", "历史与变更结果\n恢复、总结、审阅", "文件／命令／外部工具\n在选定环境执行", "策略与平台沙箱\n派生有效权限"],
    mechanism="app-server 的意义可以用远程控制来理解：界面发送结构化请求，核心把一轮中的消息、工具进度和完成状态回传。界面刷新不应让客户端重新猜任务有没有执行过。工作树则解决另一个问题：两个任务各自在不同目录改代码，减少争写文件；它不提供网络隔离，也不会自动解决两个补丁在业务逻辑上的冲突。源码中的子代理控制把容量和权限继承放进创建流程，说明分工需要运行时管理，而非只在提示里写几个角色名。",
    rows=[("项目规则", "AGENTS.md、Skills 与产品支持的记忆", "固定规范进入规则文件，当前进度进入任务记录，便于分别维护"), ("状态与界面", "任务／回合／事件通过 app-server 协议交互", "自建客户端需要正确处理审批、流式事件和任务结束"), ("上下文容量", "保留历史并按路径进行压缩", "压缩后抽查目标、文件和失败原因，必要时重新读原文"), ("并行工作", "子代理与 Git 工作树承担不同职责", "前者分工，后者隔开文件；完成后都需要集成"), ("执行环境", "本地及其他产品入口的环境与沙箱不同", "先确认当前目录、可写范围和网络访问策略"), ("交付", "文件变更、命令输出与审阅流程", "最终要检查实际 diff；任务完成标签不是业务验收")],
    steps=["选择 CLI、编辑器或桌面入口，打开目标仓库。确认当前分支和已有未提交修改，避免把用户原有工作误当作代理产物。", "检查实际工作目录、模型、权限与执行环境，让它解释项目运行方法；把长期有效的约定放进适用范围内的 AGENTS.md。", "提交完整任务，包括复现、改动边界、可运行的测试和完成标准。复杂需求先要求简短计划，确认关键接口后实施。", "检查执行证据：命令是否真的运行、返回状态如何、验证覆盖了哪些行为。没有运行条件时，明确区分静态检查与真实运行验证。", "确有独立改动再创建工作树或子任务；集成时重新做相关检查。需要开发自己的客户端时，再读 app-server 协议及事件生命周期。"],
    command="bash\n# 安装并完成认证后，在目标仓库启动\ncd /path/to/project\ncodex\n# 以下 Git 命令供交付后人工审查\ngit diff --stat\ngit diff",
    task="为现有服务增加分页查询，保留旧接口行为。先梳理调用方和测试，再实现参数校验、分页逻辑与测试。完成后解释兼容性，并列出未验证的部署条件。",
    acceptance="分页任务应覆盖正常返回、空结果、边界页和非法参数，确认各条路径都符合预期。若并行实现前后端，还要确认参数名称、排序规则和错误码一致。这个例子用来检验任务管理是否改善了交接、集成和最终交付。",
    tradeoff="它适合把实现、验证和审查作为一件连续工作的用户。原生模型路线通常省去协议适配负担；自定义 Provider 仍需确认工具参数、推理状态和上下文处理。与 Kiro 比较时看是否需要先形成规范；与轻量 Pi 比较时看是否更重视现成任务与权限管理。")

add("A03",
    principle="它把 Google 模型接进一个可读源码的开发循环。检索、图片与项目操作可以在同一任务中配合，例如先理解截图和接口文档，再修改页面。它的自然优势来自生态整合；如果只是希望所有厂商都能完全相同地工作，多 Provider 产品的设计目标会更贴近需求。",
    flow=["终端输入\n项目目标与材料", "Core Client\n消息、上下文与模型流", "Gemini／认证渠道\n模型与相关服务", "工具结果与会话\n下一轮判断", "文件／Shell／扩展\n读取、修改、验证", "Scheduler\n策略、审批与工具队列"],
    mechanism="调度器像执行现场的值班员。模型提出一批操作后，它要逐个判断能否执行、是否需要询问、是否已经被取消，再把结果交回客户端。因此，模型输出一条命令并不表示命令已经运行。扩展和 MCP 增加可用能力时，也是在这条执行链上增加工具；如果工具返回太长、错误不清楚，最终会影响下一轮推理。排查失败时应分别看模型回复、调度状态和实际进程输出。",
    rows=[("认证与费用", "Google 登录、API、Vertex 等渠道", "同一个界面不代表相同额度和组织政策"), ("项目背景", "GEMINI.md 与按需读取项目材料", "将命令和目录约定写进去，比整仓灌入更容易维护"), ("多模态与检索", "依所选模型和工具处理额外材料", "模型支持图片，不代表所有输入渠道都支持同样附件"), ("工具调度", "策略、审批、执行状态和队列分层", "失败先区分被拒绝、工具报错和模型选错动作"), ("扩展", "扩展与 MCP 等外部能力", "逐项接入，保留可复现的配置"), ("模型替换", "主要面向 Gemini 生态", "更换认证渠道后重新记录实际型号和上下文限制")],
    steps=["按仓库安装指南准备运行环境和 CLI，选择适合个人或组织的认证方式；先验证能正常调用模型。", "在测试项目运行 gemini，让它读 README 和配置文件，说明本项目怎样构建与测试。把确认后的规则写入 GEMINI.md。", "提交一个同时有材料和代码的任务，例如按接口文档补齐一个调用。明确哪些网址或附件可作为依据，以及哪些内容必须由本地代码确认。", "在执行阶段检查文件修改和命令审批；工具失败后让它解释返回信息，再决定重试或换方法。", "完成后检查引用资料是否真的支持实现，运行本地检查。再加入一个必要扩展，重复同一任务片段，确认新增能力没有破坏基本循环。"],
    command="bash\n# 先按官方要求准备运行环境\nnpm install -g @google/gemini-cli\ncd /path/to/project\ngemini",
    task="根据提供的 API 文档，在这个项目里增加天气查询页。请先确认文档中的请求参数与错误格式，再复用现有网络层；界面需要加载、成功、空结果和失败四种状态。",
    acceptance="这里需要同时核对资料理解和工程落地。能查到正确文档但没有沿用项目网络层，仍算集成失败；页面成功显示一次，也不能替代错误状态验证。记录是否出现了检索结果过多、模型只读摘要或接口版本混用。",
    tradeoff="适合已经采用 Google 服务、需要检索与多模态辅助开发的用户。主要成本不只在模型单价，也在认证配置、组织限制和扩展维护。与 Qwen Code 对照时，重点看实际需要的协议与服务渠道；比较时结合当前版本，核对两者的模型适配与工具行为。")

add("A04",
    principle="Qwen Code 把熟悉的终端代理形式与更宽的模型接入结合。它允许用户在保留一套工作习惯的同时调整模型服务，但这个自由度也要求用户了解地址、协议、认证和模型能力是四件事。它尤其适合希望围绕中文服务或自建推理环境形成稳定流程的用户。",
    flow=["终端及支持的客户端\n项目任务", "Core Client\n上下文、精简与预算", "Provider 适配\nQwen 或其他模型", "会话与任务结果\n压缩、继续与汇总", "工具／子代理\n项目目录或工作树", "工具权限与环境约束\n审批、取消传播"],
    mechanism="同一个子任务能否放进工作树，取决于运行环境是否允许它访问那个目录。源码对这类限制做了明确判断，所以不能孤立地比较功能勾选项。上下文预算也是如此：客户端可以精简和压缩材料，但服务端真实可容纳多少内容，还取决于模型部署参数。特别是在本地服务中，模型卡写着很长的窗口，并不意味着推理服务已经按相同长度启动。",
    rows=[("模型接入", "多协议与多个 Provider", "逐个确认 Base URL、认证、模型 ID 与协议"), ("项目上下文", "规则、当前历史和压缩／精简", "保留关键约束，验证长任务恢复时是否仍然有效"), ("目标控制", "客户端处理目标与预算相关状态", "预算应连同子任务用量一起观察"), ("分工", "子任务、会话、目录与权限共同管理", "沙箱条件可能限制工作树和团队模式"), ("本地模型", "可按文档接入自建兼容服务", "先通过工具调用与多轮测试，再讨论长任务"), ("迁移", "可复用项目文件与任务描述", "认证、规则优先级和插件配置仍需重新核对")],
    steps=["安装当前发行版并运行 qwen。先使用文档推荐的认证路线，避免第一步就同时自建模型、修改工具和启用团队。", "让它解释仓库入口与测试方法，补充项目指令；确认中文需求中的业务术语与代码名的对应关系。", "选择一个明确模型，用读取、单文件修改、运行检查三个动作验证基础工具链；记录返回的实际模型 ID。", "接入本地服务时，再检查服务的上下文参数、工具模板和是否支持所需多模态能力。用两三轮连续纠错检查模型能否利用工具反馈继续推进。", "基础稳定后试一个独立子任务，确认目录、权限继承和取消行为。需要工作树时先检查当前沙箱是否允许，完成后由主任务统一验证。"],
    command="bash\n# 安装与认证按当前 Qwen Code 文档完成\ncd /path/to/project\nqwen",
    task="为订单列表补充状态筛选。请先把“待支付、处理中、已完成”与代码中的枚举对应起来，再修改查询和测试。保持旧调用不传筛选条件时的行为。",
    acceptance="这个任务能发现中文业务理解与代码执行之间的落差。检查是否错把展示文案当作数据库值，是否保持了默认查询行为；若换成自建模型，观察它能否正确生成工具参数，并根据测试失败继续修正。",
    tradeoff="跨协议和中文生态选择丰富，代价是配置组合更复杂。纯原生 Gemini 工作可选 Gemini CLI，偏模型无关插件生态可比较 OpenCode，极简研究可比较 Pi。比较时固定相同模型和任务，才能判断差异来自工具设计还是模型能力。")

add("A05",
    principle="它更关心长任务中的连续性：当前目标、已经读到的文件、未完成的工具交换和接下来要做的事，都必须在多轮调用中正确衔接。大窗口有帮助，但不能替代运行时维护状态。对读很多资料、再推进多文件修改的开发任务，这种连续性通常比第一轮回答写得多长更有意义。",
    flow=["CLI／ACP 客户端\n输入与审批交互", "agent-core-v2\n组织会话与执行", "模型请求适配\nKimi／自定义 Provider", "历史与压缩策略\n保留有效工具交换", "文件、命令与插件\n执行并返回结果", "工具及子任务管理\n分派与生命周期"],
    mechanism="可以把工具调用看成一封请求与一封回信。压缩时若只留下请求，模型可能以为动作还没完成；若只留下回信，也可能不知道结果对应哪个动作。Kimi 的压缩策略对这种边界做处理，目的是给下一轮留下可解释的历史。ACP 解决的则是界面连接问题：编辑器可以展示会话，但实际循环仍由 Kimi 负责。换编辑器不等于换了模型协议或执行权限。",
    rows=[("项目身份", "当前 kimi-code 多包实现", "阅读旧 kimi-cli 教程前先核对版本和命令"), ("长任务", "上下文预算与完整工具交换共同决定压缩", "用阶段性检查点补充摘要，观察检查点与摘要能否共同保留任务约束"), ("多入口", "CLI 与 ACP 等连接方式", "外部编辑器需要单独配置代理与认证"), ("分工与扩展", "子任务、插件和 Hooks", "先验证单代理循环，再增加独立调查职责"), ("模型别名", "账户目录与别名映射可以变化", "试用记录保存实际模型 ID 与别名当时的指向"), ("兼容服务", "Provider 文档提供配置路径", "不同协议的工具、流和推理语义要重新验收")],
    steps=["从当前 kimi-code 的 README 安装发行版，在项目目录启动 kimi；配置说明也选用与该发行版对应的文档。", "在交互界面用 /login 完成认证，用 /model 查看本账户实际可用模型。核对订阅别名和 API 型号是否相同。", "先让它整理项目入口、测试命令和已有约束；提交一个需要读多个文件、但修改范围明确的任务，观察文件引用是否准确。", "长任务每完成一个阶段，要求记录已修改文件、验证结果和下一步；恢复后抽查这些事实，再继续实施。", "需要编辑器入口再配置 kimi acp；需要跨模型再按 Provider 文档增加一项配置，并重复同一组工具与恢复测试。"],
    command="bash\ncd /path/to/project\nkimi\n# 在支持 ACP 的客户端中，按文档将代理启动命令设为：\nkimi acp",
    task="阅读这套旧接口和迁移说明，列出必须保持的行为。先迁移一个模块并补测试，把尚未处理的接口写成清单；下一次会话根据清单继续。",
    acceptance="迁移后的行为比“读完了很多文件”更值得检查。对照旧测试和调用方，确认关键边界未丢失；暂停恢复后询问它仍未解决的事项，将回答与保存的进度、失败记录逐项核对。",
    tradeoff="适合 Kimi 用户、中文交流和材料较多的工程任务。长上下文能少做一些切片，但仍需承担输入成本、摘要偏差和恢复核验。与 Hermes 比较时，前者偏开发任务，后者更强调长期个人经验与多入口持续工作。")

add("A06",
    principle="MiMo Code 的一个重要判断是：工具接口会影响模型采取什么行动。模型在训练和使用中形成了不同的调用习惯，有的更适合补丁，有的更适合命令或可编程工具组合。因此，同一个任务可以保留外层会话结构，却为不同模型配置不同工具接口。这让模型适配深入到行为层，也增加了维护多条执行路径的成本。",
    flow=["CLI／任务模式\nPlan、Build 等", "会话与模型分派\n装配适用工具集", "MiMo／其他 Provider\n模型生成动作", "摘要、记忆与检查点\n供继续任务使用", "宿主工具执行\n文件、终端与外部服务", "模型特定工具层\n可选 microkernel"],
    mechanism="在可编程调用路线中，脚本可以把多次工具调用组织成一次小流程，减少来回解释。但脚本虚拟机没有直接的文件或网络访问，只能说明脚本自身的能力受限；它转而调用的宿主终端仍可能执行有影响的命令。另一个设计重心是把进度写成可装载材料：检查点应说明已经做了什么、为什么失败和怎样继续，而不只是重复最初需求。两条机制分别解决调用效率与任务连续性。",
    rows=[("模型适配", "不同家族可采用专门工具配置", "兼容结论要精确到模型、协议和工具模式"), ("任务模式", "Plan／Build／Compose 等有各自约束", "切模式前确认是否改变可写能力和工具集"), ("可编程工具", "QuickJS 等受限脚本环境", "脚本限制不等于宿主命令已被操作系统隔离"), ("长任务材料", "记忆、检索与检查点", "抽查内容是否准确、是否记录失败方案与下一步"), ("上下文", "压缩配合恢复材料", "减少输入不保证遗漏最少，需要任务验证"), ("继承与演化", "继承 OpenCode 结构并加入自身产品能力", "按当前发行版核对开关与默认值")],
    steps=["按当前 README 安装 CLI，在项目目录启动 mimo；先选官方原生模型路线，建立一条能完成修改与测试的基线。", "用 Plan 讨论任务和验收，用 Build 实施一个范围明确的改动；切换前查看实际工具与权限，不把模式名当成唯一保障。", "要求将阶段成果写进项目中可查看的记录，包含文件、检查结果、失败原因和下一步。重新开启任务后验证恢复准确性。", "确需使用其他模型时，核对其适配路径和工具配置；先运行相同小任务，观察调用格式、补丁应用和错误处理是否稳定。", "再尝试可编程工具或 Compose。单独记录它节约的是往返次数、输入量还是人工干预，避免用更复杂的流程掩盖任务返工。"],
    command="bash\n# 先满足官方运行环境要求\nnpm install -g @mimo-ai/cli\ncd /path/to/project\nmimo",
    task="把三个重复的表单校验函数抽成共享模块。请先比较差异、写出必须保持的行为，再逐个迁移；每个阶段保存检查点，最后跑相关测试。",
    acceptance="关注抽象是否保留了各表单的差异。为了减少重复而把业务例外抹平，属于失败。恢复检查点时，让它指出已迁移和未迁移的调用方；比较模型适配时，则观察同一类编辑能否稳定应用。",
    tradeoff="适合愿意研究模型与工具协同、希望任务进度可恢复的开发者。优势越依赖特殊适配，跨型号升级就越需要回归。若只需要简单多 Provider 终端工作，先比较 OpenCode；若重点是原生 MiMo 服务，MiMo Code 更值得先试。")

add("A07",
    principle="DSH 更像一套能重新装配的代理系统。一般产品允许换模型、加工具，而它还把代理循环、会话存储和子代理后端做成可替换服务。对最终用户，标准配置仍可作为编程工具；对研究者，重要的是能比较不同执行方法，而不必重写整套界面。这种开放程度很高，却不会自动带来稳定的插件组合。",
    flow=["Web／终端入口\n选定 Profile", "插件装配与会话服务\n提供代理运行能力", "模型服务插件\nDeepSeek 等后端", "事件日志\n推导历史与界面状态", "工具与子代理后端\n本机／ACP 等", "循环与调用调度\n有界并行、独占屏障"],
    mechanism="事件日志保存的是发生过的事情，例如一次工具调用请求、执行结果或错误；模型历史和界面再据此形成各自视图。这样，界面可以重建而不必再次执行工具。并行调度中，普通独立调用可以一起进行，需要独占的调用则像一扇临时关闭的门，等待前后批次衔接。开发插件时若忽略这种时序，即使每个工具单独能用，组合起来也可能发生先写后读顺序错误。",
    rows=[("装配", "Profile 选择部件，配置再覆盖", "同时记录产品版本与最终装配结果"), ("模型与循环", "模型 Provider 和代理循环都可替换", "换模型与换循环是两个实验变量"), ("历史", "事件日志作为重要状态依据", "可重建过程，不保证重跑模型产生同样输出"), ("工具", "并发上限与独占调用屏障", "依赖先后顺序的动作应明确表达依赖"), ("子代理", "内部会话、ACP 等后端接缝", "不同后端并不提供完全相同的功能"), ("成熟度", "开发者预览及快速变化的接口", "固定可用版本和插件集，升级后重做小型回归")],
    steps=["按官方 README 准备环境，使用标准入口与 Profile 启动；先确认模型认证、文件读写和工具结果展示正常。", "保存版本、Profile 和实际启用插件。让它完成一次最小修复，检查日志能否清楚区分请求、执行和结果。", "在同一配置下测试中断与恢复，确认恢复不会把已完成的工具误当成仍待执行；对有外部副作用的操作尤其要核对结果。", "有明确需求再更换一个部件，例如模型 Provider 或子代理后端；保留原配置作为对照，重复相同任务。", "开发新循环时，补齐错误、取消、权限和状态保存行为的设计，再接入 UI。能输出一个答案只是接口冒烟检查，不是代理系统验收。"],
    command="bash\n# 标准 Web 入口；按官方文档配置认证与 Profile\nnpx @deepseek-ai/dsh web",
    task="读取项目测试失败日志，修复一个独立错误。请保留关键执行证据；恢复会话后，准确说明哪些命令已成功、哪些仍待处理。",
    acceptance="先比较事件记录与真实文件，确认没有只显示成功却漏写结果。研究不同循环时固定模型、项目状态和预算，统计任务完成、工具格式错误与人工干预；每轮尽量只改变一个因素，便于解释架构调整带来的影响。",
    tradeoff="如果目标是开发、实验或嵌入代理运行时，DSH 的可替换边界值得研究。若只是日常修代码，开放性带来的收益可能小于维护预览配置的成本。与 Pi 比较时，一个侧重可理解且可扩展的核心，另一个将更多系统职责公开为装配接缝。")

add("A08",
    principle="OpenCode 把选择权放在模型和入口上：同一套会话与工具机制可以接不同 Provider，也能由不同界面使用。它对已有多个模型账户的用户很有吸引力。自由度带来的责任是明确记录究竟使用了哪个服务、哪套权限和哪些插件；“我用的是 OpenCode”本身并不足以复现一次任务。",
    flow=["CLI／桌面等客户端\n任务与用户反馈", "会话处理器\n消息、快照与模型流", "Provider／模型\n按适配生成工具请求", "历史与压缩\n近期内容、摘要", "文件／命令／子会话\n执行与汇总", "权限与工具注册\n插件、任务工具"],
    mechanism="会话处理器把流式模型回复转为可保存的消息和工具事件；某些事件先后顺序并不直观，因此不能只按终端文字出现顺序理解内部状态。快照、历史和压缩共同服务恢复，但分别处理文件状态、对话过程和窗口容量。任务工具创建的子会话可以带着派生模型与权限工作：这能分开探索细节，也可能让总账单包含多个模型。",
    rows=[("模型自由", "多个 Provider 与协议适配", "模型列表多不代表所有组合都通过同等级测试"), ("任务方式", "Plan 分析与 Build 实施", "按实际工具策略确认各模式的操作范围"), ("历史与文件", "会话记录、快照及压缩各有职责", "继续对话与恢复文件应分别验证"), ("子任务", "独立子会话、模型与权限派生", "后台等能力需确认版本和实验开关"), ("扩展", "插件、LSP、MCP 等能力", "一次增加一类能力，才能定位行为变化"), ("迁移", "模型与界面解耦降低部分绑定", "账户授权、工具格式与历史结构仍有迁移成本")],
    steps=["安装并进入仓库运行 opencode，连接一个 Provider；优先选择已经明确支持工具调用的模型，记录实际 ID。", "先用 Plan 让它解释修改范围、依赖和测试，再切换 Build 实施；将不变的项目约定写入文档支持的指令文件。", "做一次完整的小任务，包括读取、修改、运行检查和展示 diff。工具调用失败时先看协议与参数，再怀疑模型能力。", "保存任务的材料与验收条件，切换第二个模型重做同等任务；保持插件和模式一致，便于辨认模型切换带来的差异。", "长任务再试压缩与子会话。检查摘要是否保留约束、子任务是否只修改分配范围，以及合并结果能否通过统一检查。"],
    command="bash\n# 完成官方安装后，在仓库内启动\ncd /path/to/project\nopencode",
    task="将一个命令行脚本增加 dry-run 选项。预演时应展示将要发生的操作，但不修改文件；保持正常运行行为，并补上两类测试。",
    acceptance="这是适合跨模型比较的小任务：要求清楚，既需要理解控制流，又能用测试验证是否真的没有副作用。记录补丁应用失败、工具参数错误和重试次数；最终代码相同但过程成本不同，也有选型意义。",
    tradeoff="适合希望长期保留模型选择权的人。它让替换服务更容易，但没有消除服务差异。与 Kilo 比较时，关注是否需要账户与托管任务整合；与原生 Claude Code／Codex 比较时，关注模型适配成熟度及你愿意承担多少配置工作。")

add("A09",
    principle="Pi 的设计可以理解为一套可理解、可改造的工作底座。模型接口、代理循环和编码产品分层，让使用者能在某一层定制，而不必把整个项目复制后全面修改。它把许多产品偏好留给扩展，因此同名 Pi 安装之间也可能有很大差异。简洁的价值在于职责清楚，使用者更容易理解和调整工作流程。",
    flow=["交互／脚本／嵌入入口\n任务与中途引导", "coding-agent 会话层\n历史、分支与扩展", "pi-ai\n多 Provider 模型接口", "会话事件与结果\n保存、切分、恢复", "工具与扩展回调\n文件、命令及自定义能力", "agent-core 循环\n工具分派与后续消息"],
    mechanism="模型适配包负责把不同服务的消息与流接到统一接口；代理核心处理下一轮、工具和中途引导；编码产品再加入会话树、终端 UI 与扩展。扩展既可以增加一个工具，也能在关键事件中调整行为，所以比较 Pi 的实验应记录扩展清单。会话树帮助你从某个思路重新开始，但此前写入磁盘的文件还在原处；想同时保留两套代码实验，仍需要独立目录或 Git 工作树。",
    rows=[("分层", "pi-ai、agent-core、coding-agent", "改模型接口与改产品交互不必落在同一层"), ("历史", "分支、模型变更和压缩等会话事件", "对话树不是文件系统快照"), ("扩展", "工具、命令、事件、Provider、UI", "说明所装扩展与版本，才能复现工作方式"), ("分工与计划", "可由扩展补充具体编排体验", "记录具体扩展及其配置，说明能力来自哪里"), ("权限", "默认没有内置系统权限限制", "工具和扩展按启动进程的权限运行"), ("隔离", "可采用容器或文档中的隔离方案", "核对宿主挂载、网络和凭据，不能只看容器名称")],
    steps=["使用当前官方包名与安装说明，先运行最小配置。配置一个稳定的工具模型，确认终端中能看到文件操作和结果。", "在一次性测试项目中完成小修改；先了解启动进程可访问什么，再决定是否用容器或其他隔离环境。", "观察会话历史和分支功能。尝试从较早节点改变方案，然后检查磁盘，理解聊天状态与文件状态的区别。", "只安装一个有明确用途的扩展，例如固定检查或任务分工。查看它注册了什么工具、监听哪些事件，再重复基础任务。", "要开发自己的 Harness 时，先选需要复用的层；尽量在公开扩展接口内实现需求，确需改变核心语义再修改循环。"],
    command="bash\n# 当前仓库使用的新包名；安装前核对 README 的环境要求\nnpm install -g --ignore-scripts @earendil-works/pi-coding-agent\ncd /path/to/project\npi",
    task="比较这个模块的两种重构办法。先读代码并给出取舍，再在一个独立代码分支上实现方案 A；保留一份说明，便于随后用相同测试比较方案 B。",
    acceptance="用这个任务理解“思路分支”和“代码分支”两个层次。观察切换对话后是否仍知道实际文件状态；加入扩展前后比较工具集合、运行轮次和人工修正。比较时列明双方的扩展和配置，将核心与扩展各自的影响分开讨论。",
    tradeoff="它尤其适合终端熟手、研究者和想写自己工作方式的人。代价是权限、团队流程和扩展质量需要更主动地管理。若希望这些产品决策已经替你做好，可以比较 Step Code、Cline 或完整 IDE；如果乐于自己决定，Pi 的分层更有价值。",
    sources="[编码代理安装与使用](https://github.com/earendil-works/pi/blob/b4588f26af2f74f7b1387b548e04a3c8d81da75b/packages/coding-agent/README.md)")

add("A10",
    principle="Cline 的起点是让用户看见过程并参与决定。它适合希望知道代理为什么读这个文件、为什么执行这条命令的人。Plan 与执行阶段帮助用户先对齐思路，再让代理动手。随着 CLI 和 SDK 发展，同一品牌的用途已经更广；选型时仍要把编辑器中的透明交互与命令行中的团队编排分别判断。",
    flow=["编辑器／CLI／SDK\n用户目标与审批", "代理运行时\n消息、重试与停止", "Provider 适配\n模型与工具格式", "会话及上下文管理\n预算、压缩和交接", "项目工具与研究子任务\n执行后返回结果", "工具授权与入口能力\n按部署暴露功能"],
    mechanism="把研究交给只读子代理的好处是减少主会话噪声：它可以阅读相关文件，再返回路径和发现。主代理负责据此修改，不必接收每一次搜索输出。团队任务则多出共享任务板、消息和长期状态，需要处理工作交接。两者解决的问题不一样：只读探索无法替代多个可写工作者；有团队状态也不能免去最终集成检查。",
    rows=[("交互", "操作过程与审批可见", "根据具体风险授权，避免机械地全部点同意"), ("规划", "Plan 与执行工作方式", "计划中要有改动边界和验收，不只是步骤数量"), ("只读研究", "普通 Subagents 独立探索并汇总", "不默认拥有任意编辑或继续派生能力"), ("团队", "CLI／SDK 等有独立团队机制", "所核验文档未把同等能力开放给所有 IDE 扩展"), ("模型与错误", "多 Provider、重试和输出限制处理", "协议错误、限流和真正推理失败要区分"), ("上下文", "独立压缩管线与预算管理", "长任务要保存关键约束并抽查交接摘要")],
    steps=["安装自己常用编辑器的当前扩展，完成 Provider 与模型配置；检查账单所属服务以及自动批准范围。", "用 Plan 请求梳理问题和相关文件，先阅读方案。明确哪些文件可改、怎样运行测试，再进入执行。", "跟随一轮读取、修改与检查，查看工具请求和实际结果；遇到不理解的操作时，及时询问依据并补充约束。", "代码库较大时，再让只读研究子代理调查独立问题；要求返回文件位置与证据，由主代理统一实施。", "确需共享任务板和多工作者时改用相应 CLI／SDK 路线，先做一个可拆分试点；先核对团队功能在哪个入口开放。"],
    command="text\n操作路线：安装 Cline 扩展 → 配置 Provider／模型\n→ Plan 核对方案 → 执行并审阅工具操作 → 检查 diff 与测试\n需要 Agent Teams 时，另按 CLI／SDK 的专门文档配置。",
    task="这个页面偶尔重复发送请求。先追踪事件绑定与副作用，再说明最可能的原因；经核对后修复，验证首次加载、参数变化和快速点击三条路径。",
    acceptance="观察它是否能把每一次搜索和修改连回具体假设。如果只是遍历很多文件，却没有提出可验证的解释，可要求收缩范围。这个试用主要检验透明交互能否帮助你参与判断；对新手而言，比一次生成多少行代码更重要。",
    tradeoff="适合愿意逐步参与、希望在熟悉编辑器中学习代码与检查结果的人。频繁审批可能打断节奏，放宽审批又会减少人工观察；需要根据任务调整。可分别与 Cursor 比较编辑体验、与 CLI 团队产品比较任务交接，按问题组织结论。")

add("A11",
    principle="Kilo 的产品选择是把开放执行核心与统一服务入口结合：用户既能享受多模型选择，也能使用账户、托管任务和审查等整合功能。它适合不想为每个模型重新准备界面的人。判断其价值时应把代理本身、模型转发和云服务分别列出来，才能看清自己实际购买了什么。",
    flow=["IDE／CLI／云端入口\n任务与账户", "Kilo 会话层\n产品行为与恢复", "模型路由／自有 Key\n所选 Provider", "历史与压缩衔接\n溢出处理和恢复", "文件及项目工具\n本地或远端执行", "OpenCode 核心相关层\n工具、权限与流处理"],
    mechanism="相同核心血缘不意味着相同产品。会话出错时怎样解释、是否先压缩后重试、模型目录怎样更新，都可能改变实际完成率。另一方面，云端任务多了环境与账户服务，本地可用的凭据未必在远端存在。迁移时应拆开四类东西：代码文件、项目规则、会话状态与服务授权；只有代码能打开，不能证明完整流程已经迁移。",
    rows=[("入口", "CLI、编辑器与云端服务", "分别确认运行目录、授权和功能范围"), ("模型", "托管路由与自有 Provider 选择", "BYOK 不代表其他平台能力也不收费"), ("执行核心", "当前包含 OpenCode 结构及 Kilo 会话层", "旧 Roo／Cline 教程不能自动代表现版"), ("恢复", "错误信息、上下文溢出和压缩衔接", "检查重试是否保留任务约束与有效工具结果"), ("协作", "按当前产品提供远程任务和审查等能力", "分别核对本地扩展与云服务的职责"), ("迁移", "规则、模型、历史与权限分别处理", "先迁一条完整任务，再迁全部配置")],
    steps=["先选一个常用入口完成安装，决定使用 Kilo 模型服务还是自己的 Provider；记录模型账单和平台账单的边界。", "导入一个小项目，确认当前模式、项目规则和执行权限。让它先说明运行方法，再实施一个易验收的修复。", "查看 diff 与执行证据，记录调用成本和等待时间；失败时区分路由、限流、上下文溢出与代码问题。", "需要远程任务时，另配置仓库访问与环境。用不依赖本机特殊文件的小任务验证，再把其他工作交出去。", "迁移旧配置时逐项核对规则、模式、MCP 和认证，不直接复制全部目录；升级后重复同一条基础任务。"],
    command="text\n试用记录至少包含：\n入口与版本：IDE／CLI／云端\n模型渠道：Kilo 托管／自有 Provider\n实际模型 ID、启用模式、工具权限\n任务结果、模型费用、其他服务费用",
    task="给这个工具增加 CSV 导出，并沿用已有列表筛选逻辑。先在当前入口实现与测试；若再交给云端，使用同一仓库状态和验收条件比较。",
    acceptance="检查导出字段、编码和筛选结果是否一致；云端还要核对依赖和文件能否保存取回。评估产品整合带来的便利时，把登录、环境准备、模型调用和结果审查的人工时间一起记录。",
    tradeoff="更适合既重视模型选择，又愿意使用整合服务的开发者。与 OpenCode 的差别不应只看共同源码，而应看账户、远程能力、错误恢复和费用；与单厂商原生代理相比，则更需要自己验收模型组合。")

add("A12",
    principle="Goose 把外部工具接入放在中心。开发任务往往需要同时读取仓库、查询资料或检查业务系统，它希望在同一代理会话中组织这些能力。MCP 扩展让接入更标准化，但标准化的是调用方式，不是业务权限或返回数据质量。工具接得越多，越需要先想清楚这个任务真正需要哪些能力。",
    flow=["桌面／CLI／ACP 入口\n任务与用户反馈", "Rust Agent 核心\n上下文与会话", "Provider／可选代理后端\n生成下一步动作", "结果与上下文策略\n摘要、恢复与结束", "MCP 扩展及其他工具\n业务服务与项目文件", "工具选择与权限\n分派和执行管理"],
    mechanism="在一次跨系统查询中，模型会选择一个工具并提供参数，扩展实际连接服务，把结构化结果返回，再由代理决定是否继续。工具描述不清楚或返回整张数据库表，会让后续推理更困难。Goose 的上下文管理先主动处理容量，必要时再采用后备策略；这可以缓解长工具输出，但摘要之后仍应保留能复查的记录编号与来源。",
    rows=[("工具接入", "MCP 扩展是主要能力组织方式", "先明确只读查询还是允许写回"), ("运行核心", "Rust Agent 管模型、工具与会话", "界面和执行逻辑分开核验"), ("上下文", "主动压缩与溢出后备策略", "桌面与 CLI 的可选策略可能不同"), ("ACP", "既可作为被驱动代理，也有其他后端路线", "记录是换了界面，还是换了执行核心"), ("模型", "多 Provider 与可靠工具模型", "工具参数正确率比聊天风格更关键"), ("数据路径", "模型、扩展服务和本机各有边界", "本地桌面不等于业务资料留在本机")],
    steps=["选择桌面或 CLI 安装，配置一个模型 Provider，先只用基本项目能力完成一轮读取和输出。", "增加一个与真实工作有关的扩展，例如只读数据查询；检查认证身份、可见范围和工具描述。", "给出资料来源与输出要求，让代理先查询再形成报告。核对查询参数和原始结果，确认没有凭空补齐缺失事实。", "长输出任务保存关键记录 ID、筛选条件与统计方法，再观察压缩后能否继续正确工作。", "需要跨系统写回或代理后端接入时再单独增加；按实际权限和后端验证取消、失败及恢复行为，避免把普通查询成功推及所有能力。"],
    command="text\n配置顺序：Provider → 一个必要扩展 → 认证身份与权限\n试用顺序：只读查询 → 保存结果 → 复查来源 → 再考虑写回\n每增加一个扩展，重做一次基础查询与结果核对。",
    task="读取本项目的错误日志，并通过已配置的只读工具查询对应工单。整理成问题分类表，保留工单链接、发生次数和待确认原因，先生成本地报告。",
    acceptance="检查日志统计与工单关联是否可靠；相似标题不一定属于同一故障。这个任务能检验工具组合是否真正减少手工查找，以及长输出后来源是否仍能复核。接入多个工具并不意味着要让模型每次都用一遍。",
    tradeoff="适合开发与业务资料交叉、已有 MCP 服务的场景。代价是连接器、身份和权限维护，往往比安装 Goose 本体更复杂。若只是改仓库里的代码，普通编码代理可能更省事；需要团队共享门户时，则应再比较服务型产品。")
